\title{The Mega-Sphere: Encoding All Dimensions in a Single Object}
\author{Aristotle}
\date{July 11, 2026}

\begin{document}

\begin{abstract}
We develop, from three complementary directions, the principle that an infinite
family of mathematical structures --- one per dimension or stage --- can be
captured by a single algebraic object, and we sharpen the sometimes
counterintuitive behavior of these ``all-at-once'' objects. First, working with
inverse limits of towers of additive groups, we prove a general collapse
theorem: for every integer $d$ with $|d| \ge 2$, the multiplication tower
$\Z \xleftarrow{\times d} \Z \xleftarrow{\times d} \cdots$ has trivial inverse
limit. We disprove the tempting conjecture that a tower of nontrivial groups
must have nontrivial inverse limit, and we prove a positive Mittag-Leffler-type
result: towers with surjective connecting maps surject onto their bottom stage.
Second, in the arithmetic of Bernoulli numbers, we record the single
exponential generating identity $\bigl(\sum_n B_n x^n/n!\bigr)(e^x-1) = x$ that
encodes all Bernoulli numbers at once, disprove the conjecture that all
odd-indexed Bernoulli numbers vanish (since $B_1 = -\tfrac12$), and establish
that for every exponent $p$ the running power sum $n \mapsto \sum_{k<n} k^p$ is
a single polynomial in $n$. Third, modeling
$H^*(\RP^\infty;\F_2)\cong\F_2[w]$, we prove the finite/infinite dichotomy that
$w$ is not nilpotent in the infinite ring but nilpotent in every truncation,
compute the Poincar\'e count, and establish the Whitney--Frobenius identity
$(1+w)^{2^k}=1+w^{2^k}$ together with the fact that all dual Stiefel--Whitney
classes equal $1$.
\end{abstract}

\maketitle

\section{Introduction}

Much of mathematics is organized by dimension or by stage: the spheres
$S^0, S^1, S^2, \dots$; the projective spaces $\RP^0 \subset \RP^1 \subset
\cdots$; the partial power sums $\sum_{k<n} k^p$; the Bernoulli numbers
$B_0, B_1, B_2, \dots$. A powerful and recurring idea is to replace such an
infinite family by a \emph{single object} that encodes the whole family and
from which each member is recovered as a projection or coefficient. We call
this the \emph{mega-object} principle, and, following the guiding metaphor of a
limit of spheres across all dimensions, the \emph{mega-sphere} program.

Two general mechanisms realize the principle. \emph{Inverse limits} assemble a
tower $X_0 \xleftarrow{\pi_0} X_1 \xleftarrow{\pi_1} \cdots$ into the collection
of coherent threads. \emph{Generating objects} encode an infinite sequence in a
single power series or polynomial. The purpose of this paper is to test the
principle: all-at-once objects may collapse (be far smaller than the individual
stages suggest), and may satisfy a clean law almost everywhere while breaking
it at one exceptional point. We make both phenomena precise, prove sharp
positive counterparts, and organize everything around inverse limits, Bernoulli
numbers, and Stiefel--Whitney classes.

\section{Preliminaries}

We write $\F_2 = \Z/2$ for the two-element field and $|d|$ for the absolute
value of an integer. For a ring $R$, $R[x]$ denotes polynomials and
$R\llbracket x\rrbracket$ formal power series; $[x^k]$ is coefficient
extraction.

\begin{definition}[Inverse limit]
A \emph{tower of additive groups} is a family $(X_n)_{n\in\N}$ of additive
groups with connecting homomorphisms $\pi_n \colon X_{n+1} \to X_n$. Its
\emph{inverse limit} is the additive subgroup of $\prod_n X_n$
\[
  \invlim X_n = \{\, x = (x_n)_n : \pi_n(x_{n+1}) = x_n \text{ for all } n \,\},
\]
whose elements are the \emph{coherent threads}. For each $n$ the
\emph{projection} is $p_n\colon \invlim X_n \to X_n$, $p_n(x) = x_n$.
\end{definition}

That $\invlim X_n$ is a subgroup follows from additivity of each $\pi_n$: the
zero thread is coherent, and sums and negatives of coherent threads are
coherent.

\section{Inverse limits: collapse, disproof, and Mittag-Leffler}

\begin{lemma}\label{lem:div}
Let $d$ be an integer with $|d| \ge 2$. If an integer $a$ is divisible by $d^n$
for every $n \in \N$, then $a = 0$.
\end{lemma}
\begin{proof}
Suppose $a \neq 0$. Since $|d| \ge 2$, the powers $|d|^n$ are unbounded; choose
$n$ with $|d|^n > |a|$. From $d^n \mid a$ and $a \neq 0$ we get
$|d|^n \le |a|$, a contradiction. Hence $a = 0$.
\end{proof}

\begin{definition}[Multiplication tower]
For an integer $d$, the \emph{multiplication tower} has $X_n = \Z$ for all $n$
and every connecting map equal to multiplication by $d$.
\end{definition}

\begin{lemma}\label{lem:thread}
For a coherent thread $x = (x_m)_m$ of the multiplication tower and all
$m, k \in \N$, one has $x_m = d^k\, x_{m+k}$.
\end{lemma}
\begin{proof}
Induction on $k$: the base case is trivial, and coherence gives
$x_{m+k} = d\,x_{m+k+1}$, so $x_m = d^k x_{m+k} = d^{k+1} x_{m+k+1}$.
\end{proof}

\begin{theorem}[Collapse of the multiplication tower]\label{thm:collapse}
For every integer $d$ with $|d| \ge 2$, the multiplication tower has trivial
inverse limit: $\invlim \Z = \{0\}$.
\end{theorem}
\begin{proof}
Let $x = (x_m)_m$ be coherent and fix $m$. By Lemma~\ref{lem:thread},
$d^k \mid x_m$ for every $k$; by Lemma~\ref{lem:div}, $x_m = 0$. As $m$ was
arbitrary, $x = 0$.
\end{proof}

\begin{definition}[Zero tower]
The \emph{zero tower} has $X_n = \F_2$ for all $n$ and every connecting map the
zero homomorphism.
\end{definition}

\begin{theorem}[Nontrivial stages, trivial limit]\label{thm:disproof}
There is a tower of additive groups in which every stage is nontrivial, yet the
inverse limit is $\{0\}$. Hence the conjecture ``the inverse limit of a tower
of nontrivial groups is nontrivial'' is false.
\end{theorem}
\begin{proof}
Take the zero tower: each stage $\F_2$ is nontrivial. If $x$ is coherent then
$x_n = \pi_n(x_{n+1}) = 0$ for all $n$, so $\invlim X_n = \{0\}$.
\end{proof}

\begin{theorem}[Mittag-Leffler for $\N$-towers]\label{thm:ML}
Let $(X_n,\pi_n)$ be a tower with every $\pi_n$ surjective. Then the bottom
projection $p_0\colon \invlim X_n \to X_0$ is surjective.
\end{theorem}
\begin{proof}
Given $a \in X_0$, set $x_0 = a$ and recursively pick $x_{n+1}$ with
$\pi_n(x_{n+1}) = x_n$ (possible by surjectivity). The resulting thread is
coherent and $p_0(x) = a$.
\end{proof}

\section{Bernoulli numbers: one function for the whole sequence}

\begin{definition}[Bernoulli generating series]
The Bernoulli numbers $B_n \in \Q$ are the coefficients determined by
$\sum_{n\ge 0} B_n x^n/n! = x/(e^x - 1)$.
\end{definition}

\begin{theorem}[Mega generating identity]\label{thm:gen}
As formal power series over $\Q$,
\[
  \left(\sum_{n=0}^{\infty} B_n \frac{x^n}{n!}\right)(e^x - 1) = x.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The coefficient of $x^N$ on the left, times $N!$, is the binomial convolution
$\sum_{i=0}^{N-1}\binom{N}{i}B_i$, which the defining recursion of the Bernoulli
numbers makes equal to $0$ for $N \ge 2$ and $1$ for $N = 1$ --- exactly the
coefficients of $x$.
\end{proof}

\begin{theorem}\label{thm:vals}
$B_1 = -\tfrac12$ and $B_4 = -\tfrac{1}{30}$.
\end{theorem}
\begin{proof}[Proof sketch]
The $N=2$ instance of $\sum_{i<N}\binom{N}{i}B_i = 0$ reads $B_0 + 2B_1 = 0$, so
$B_1 = -\tfrac12$. Using $B_3 = 0$, the $N=5$ instance
$B_0 + 5B_1 + 10B_2 + 10B_3 + 5B_4 = 0$ gives $5B_4 = -\tfrac16$, so
$B_4 = -\tfrac{1}{30}$.
\end{proof}

\begin{theorem}[Not all odd Bernoulli numbers vanish]\label{thm:odd}
The statement ``for every odd $n$, $B_n = 0$'' is false.
\end{theorem}
\begin{proof}
It would force $B_1 = 0$, but $B_1 = -\tfrac12 \neq 0$.
\end{proof}

The correct statement is that $B_n = 0$ for odd $n \ge 3$, with $B_1$ the unique
exception.

\begin{theorem}[Faulhaber's formula]\label{thm:faul}
For all $n,p \in \N$,
$\sum_{k=0}^{n-1} k^p = \frac{1}{p+1}\sum_{i=0}^{p}\binom{p+1}{i}B_i\,n^{p+1-i}$.
\end{theorem}

\begin{theorem}[Degree four]\label{thm:faul4}
For all $n$, $\displaystyle\sum_{k=0}^{n-1} k^4 =
\frac{(n-1)\,n\,(2n-1)\,(3n^2-3n-1)}{30}$.
\end{theorem}
\begin{proof}[Proof sketch]
Both sides agree at $n=0$ and have equal successive differences $n^4$, so they
agree for all $n$ by induction. The denominator $30$ is that of $B_4$.
\end{proof}

\begin{theorem}[Faulhaber polynomiality]\label{thm:poly}
For every $p \in \N$ there is a single polynomial $P \in \Q[x]$ with
$\sum_{k=0}^{n-1} k^p = P(n)$ for all $n$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:faul}, the left side is the evaluation at $n$ of the fixed
polynomial $P = \sum_{i=0}^{p} \frac{\binom{p+1}{i}B_i}{p+1}\,x^{p+1-i}$, which
does not depend on $n$.
\end{proof}

\section{Stiefel--Whitney classes: the cohomology of $\RP^\infty$}

We model $H^*(\RP^\infty;\F_2) \cong \F_2[w]$ by polynomials over $\F_2$ with
$w$ the first Stiefel--Whitney class, and use truncations and completions.

\begin{theorem}[$w$ is not nilpotent]\label{thm:nonnil}
In $\F_2[w]$, every power $w^n$ is nonzero.
\end{theorem}
\begin{proof}
If $w^n = 0$, evaluating at $w = 1$ gives $1 = 0$ in $\F_2$, a contradiction.
\end{proof}

\begin{theorem}[$w$ is nilpotent in truncations]\label{thm:nil}
For each $n$, in $\F_2[w]/(w^{n+1}) \cong H^*(\RP^n;\F_2)$ the image of $w$
satisfies $w^{n+1} = 0$.
\end{theorem}
\begin{proof}
$w^{n+1}$ lies in the ideal $(w^{n+1})$, so it is zero in the quotient.
\end{proof}

\begin{theorem}[Poincar\'e count]\label{thm:poincare}
The degree-$<n$ part of $\F_2[w]$ has $\F_2$-dimension $n$; the Poincar\'e
series is $1 + t + t^2 + \cdots = \tfrac{1}{1-t}$.
\end{theorem}
\begin{proof}
The monomials $1, w, \dots, w^{n-1}$ form a basis, so the dimension equals $n$.
\end{proof}

\begin{theorem}[Whitney--Frobenius identity]\label{thm:frob}
In $\F_2\llbracket w\rrbracket$, $(1+w)^{2^k} = 1 + w^{2^k}$ for all $k$.
\end{theorem}
\begin{proof}
$\F_2\llbracket w\rrbracket$ has characteristic $2$, so $x \mapsto x^{2^k}$ is a
ring homomorphism; hence $(1+w)^{2^k} = 1 + w^{2^k}$.
\end{proof}

\begin{theorem}[All dual classes equal $1$]\label{thm:dual}
If $(1+w)\,y = 1$ in $\F_2\llbracket w\rrbracket$, then $[w^k]y = 1$ for all $k$;
equivalently $(1+w)^{-1} = 1 + w + w^2 + \cdots$.
\end{theorem}
\begin{proof}
Comparing coefficients in $(1+w)y = y + wy = 1$: the constant term gives
$[w^0]y = 1$, and for $k \ge 1$, $[w^k]y + [w^{k-1}]y = 0$, so
$[w^k]y = [w^{k-1}]y$. By induction all coefficients equal $1$.
\end{proof}

\section{Applications and future directions}

The generating identity (Theorem~\ref{thm:gen}) is the gateway to
$\zeta(2k) = (-1)^{k+1}B_{2k}(2\pi)^{2k}/(2\,(2k)!)$ and to the von
Staudt--Clausen theorem on denominators. The finite/infinite dichotomy
(Theorems~\ref{thm:nonnil}--\ref{thm:nil}) is the algebraic shadow of
$\RP^\infty = B(\Z/2)$ approximated by finite $\RP^n$. The collapse and
Mittag-Leffler results (Theorems~\ref{thm:collapse}--\ref{thm:ML}) are
prototypes for the vanishing of $\invlim^1$ and the role of surjectivity in
homological algebra, with the $p$-adic integers $\Z_p$ as the non-collapsing
companion (its tower uses surjective quotient maps).

Future work includes: formalizing $\invlim^1 = 0$ for surjective towers and
identifying $\invlim \Z/p^n$ with $\Z_p$ as a topological ring; connecting
Bernoulli numbers to zeta special values and von Staudt--Clausen; and extending
the single-generator model to the full ring of universal characteristic classes
and its Steenrod action.

\section{Conclusion}

Across inverse limits, Bernoulli numbers, and Stiefel--Whitney classes, one
principle recurs: an infinite family indexed by dimension or stage can be
packaged into a single algebraic object with a life of its own. It may collapse
where the stages are rich, obey a clean law with exactly one exception, or be
infinite-dimensional yet governed by the simplest series. The mega-object makes
the genuine structure --- and the genuine exceptions --- visible all at once.

\end{document}

