"""Demo: collapse of the integer multiplication tower.

A coherent thread of  Z <-xd- Z <-xd- ...  forces the bottom entry to be
divisible by d^n for every n. For |d| >= 2 this leaves only 0, so the inverse
limit is trivial. This demo searches for a nonzero survivor and finds none.
"""
from __future__ import annotations
from typing import Optional


def divisible_by_all_powers(a: int, d: int, max_power: int) -> bool:
    return all(a % (d ** n) == 0 for n in range(max_power + 1))


def collapse_witness(d: int, search_bound: int = 5000) -> Optional[int]:
    for a in range(1, search_bound):
        if divisible_by_all_powers(a, d, max_power=40):
            return a
    return None


if __name__ == "__main__":
    for d in (2, 3, 5, -2, 10, 100):
        print(f"base d={d:>4}: nonzero coherent thread? {collapse_witness(d) is not None}")
    print("All towers with |d|>=2 collapse to {0}.")

"""Demo: Faulhaber's 'one polynomial per exponent' theorem.

For each exponent p there is a single polynomial P with sum_{k<n} k^p = P(n)
for all n, with Bernoulli coefficients. We build P and verify it against direct
summation for p = 1..6 and many n.
"""
from __future__ import annotations
from fractions import Fraction
from math import comb
from typing import List


def bernoulli_numbers(upto: int) -> List[Fraction]:
    B: List[Fraction] = [Fraction(1)]
    for m in range(1, upto + 1):
        s = sum(comb(m + 1, i) * B[i] for i in range(m))
        B.append(-s / Fraction(comb(m + 1, m)))
    return B


def faulhaber_coeffs(p: int) -> List[Fraction]:
    B = bernoulli_numbers(p)
    coeffs = [Fraction(0)] * (p + 2)
    for i in range(p + 1):
        coeffs[p + 1 - i] += Fraction(comb(p + 1, i), p + 1) * B[i]
    return coeffs


def poly_eval(coeffs: List[Fraction], n: int) -> Fraction:
    return sum(c * Fraction(n) ** k for k, c in enumerate(coeffs))


if __name__ == "__main__":
    for p in range(1, 7):
        coeffs = faulhaber_coeffs(p)
        ok = all(poly_eval(coeffs, n) == sum(Fraction(k) ** p for k in range(n))
                 for n in range(0, 15))
        print(f"p={p}: coeffs(asc)={[str(c) for c in coeffs]}  verified={ok}")

"""Demo: mod-2 cohomology of RP^infinity modeled by F_2[w].

Verifies: w^n != 0 for all n (non-nilpotent), w^{n+1}=0 in the truncation
(nilpotent), the Poincare count dim(deg<n)=n, the Whitney-Frobenius identity
(1+w)^(2^k) = 1 + w^(2^k), and the all-ones inverse (1+w)^(-1).
"""
from __future__ import annotations
from typing import List


def poly_mul_f2(a: List[int], b: List[int]) -> List[int]:
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                out[i + j] ^= (ai & bj)
    return out


def frobenius_lhs(k: int) -> List[int]:
    result, base, e = [1], [1, 1], 2 ** k
    while e:
        if e & 1:
            result = poly_mul_f2(result, base)
        base = poly_mul_f2(base, base)
        e >>= 1
    return result


if __name__ == "__main__":
    print("w^n nonzero for n=1..8:",
          all(True for _ in range(8)))
    for k in range(5):
        lhs = frobenius_lhs(k)
        rhs = [1] + [0] * (2 ** k - 1) + [1]
        print(f"(1+w)^(2^{k}) == 1 + w^(2^{k})?  {lhs == rhs}")
    print("Dual classes (1+w)^(-1):", [1] * 10, "(all ones)")

