function BERNOULLI(N):
    B[0] <- 1
    for m in 1..N:
        s <- sum over i in 0..m-1 of C(m+1, i) * B[i]
        B[m] <- -s / C(m+1, m)
    return B[0..N]

function FAULHABER(p):
    B <- BERNOULLI(p)
    coeffs <- array of zeros of length p+2
    for i in 0..p:
        coeffs[p+1-i] <- coeffs[p+1-i] + C(p+1,i)*B[i]/(p+1)
    return coeffs  # ascending powers of x

function WHITNEY_FROBENIUS(k):
    result <- [1];  base <- [1,1];  e <- 2^k
    while e > 0:
        if e is odd: result <- MUL_F2(result, base)
        base <- MUL_F2(base, base);  e <- floor(e/2)
    return result == [1] + zeros(2^k - 1) + [1]

