from typing import List


def poly_mul_f2(a: List[int], b: List[int]) -> List[int]:
    """Multiply two F_2-coefficient polynomials (ascending 0/1 lists)."""
    out = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                out[i + j] ^= (ai & bj)
    return out


def whitney_frobenius(k: int) -> bool:
    """Verify (1 + w)^(2^k) = 1 + w^(2^k) in F_2[w] by repeated squaring."""
    result, base, e = [1], [1, 1], 2 ** k
    while e:
        if e & 1:
            result = poly_mul_f2(result, base)
        base = poly_mul_f2(base, base)
        e >>= 1
    return result == [1] + [0] * (2 ** k - 1) + [1]

